"""CCAR-F part A: Domain 1 (Agentic Architecture and Orchestration) and Domain 2 (Tool Design and MCP Integration).

Written against the official Claude Certified Architect - Foundations exam guide (version 1.0,
effective July 2026): task statements 1.1-1.7 (27%) and 2.1-2.5 (18%). Product facts were checked
against the current Claude API, Claude Agent SDK, Claude Code and Model Context Protocol
documentation (October 2026). Part B (data/ccarf_b.py) owns domains 3-5 and starts its ids at 1001.
"""


def _fc(i, cat, front, back, detail):
    return {'id': i, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(i, cat, question, answer, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _cq(cid, n, qtype, question, explanation, options=None, correct=None, answer=None):
    """A case-study question: id is '<case id>-q<n>'."""
    q = {'id': '%s-q%d' % (cid, n), 'type': qtype, 'question': question, 'explanation': explanation}
    if qtype in ('mc', 'ms'):
        q['options'] = options
        q['correct'] = correct
    else:
        q['answer'] = answer
    return q


_AG = 'agentic'
_TL = 'tools'

FLASHCARDS = []
QUESTIONS = []
LESSONS = []
MADLIBS = []
SEQUENCES = []
CASE_STUDIES = []
COMPARE = []
CHEAT_SHEET = []


